resource "aws_s3_bucket" "finance_records" {
  bucket = "corp-finance-records-q3"
  acl    = "public-read"

  tags = {
    Environment = "Production"
    Owner       = "Finance"
  }
}

resource "aws_security_group" "bastion_sg" {
  name        = "bastion-sg"
  description = "Bastion host security group"
  vpc_id      = "vpc-0123456789abcdef0"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}
